def car_race_collision(n: int):
    def calculate_collision_time(pos1, pos2, speed1, speed2):
        if speed1 <= speed2:
            return float('inf')
        return (pos2 - pos1) / (speed1 - speed2)

    positions_left = [2 * i for i in range(n)]
    positions_right = [2 * i + 1 for i in range(n)]
    speeds = [1] * n

    collisions = 0
    for i in range(n):
        for j in range(n):
            if positions_left[i] < positions_right[j]:
                collision_time = calculate_collision_time(positions_left[i], positions_right[j], speeds[i], speeds[j])
                if collision_time < min(speeds):
                    collisions += 1

    return collisions
